def check_integer(text):
    """Check if a string represents an integer or not.

    An optional leading '+' or '-' sign followed by one or more digits
    is considered an integer. Leading/trailing whitespace is ignored.
    """
    text = text.strip()
    if not text:
        return False
    if text[0] in '+-':
        return len(text) > 1 and text[1:].isdigit()
    return text.isdigit()

