def search(arr):
    """Find the element that appears only once in a sorted array.

    All other elements appear exactly twice. Uses binary search in O(log n):
    before the single element, pairs start at even indices; after it, pairs
    start at odd indices.
    """
    lo, hi = 0, len(arr) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if mid % 2 == 1:
            mid -= 1  # align mid to the start of a pair
        if arr[mid] == arr[mid + 1]:
            lo = mid + 2  # single element is to the right
        else:
            hi = mid  # single element is at mid or to the left
    return arr[lo]

