def amicable_numbers_sum(limit):
    """Sum all amicable numbers from 1 to `limit` (inclusive).

    Two distinct numbers a and b form an amicable pair when the sum of the
    proper divisors of a equals b and the sum of the proper divisors of b
    equals a. Only pairs whose members both lie within [1, limit] contribute.
    """
    if not isinstance(limit, int) or limit < 1:
        return 0

    def sum_proper_divisors(n):
        if n <= 1:
            return 0
        total = 1
        i = 2
        while i * i <= n:
            if n % i == 0:
                total += i
                other = n // i
                if other != i:
                    total += other
            i += 1
        return total

    total = 0
    for a in range(2, limit + 1):
        b = sum_proper_divisors(a)
        if b > a and b <= limit and sum_proper_divisors(b) == a:
            total += a + b
    return total


if __name__ == "__main__":
    assert amicable_numbers_sum(999) == 504
    assert amicable_numbers_sum(300) == 504
    assert amicable_numbers_sum(95) == 0
    assert amicable_numbers_sum(1) == 0
    print("All tests passed.")

