def max_sum(arr):
    """
    Find the maximum sum of a bitonic subsequence of the given array.
    A sequence is bitonic if it is first increasing and then decreasing.

    Approach:
      - inc[i]: maximum sum of an increasing subsequence ending at index i.
      - dec[i]: maximum sum of a decreasing subsequence starting at index i.
      - For each index i treated as the "peak", the best bitonic sum is
        inc[i] + dec[i] - arr[i] (arr[i] counted once).
    """
    n = len(arr)
    if n == 0:
        return 0

    # Max sum of increasing subsequence ending at i
    inc = arr[:]
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i] and inc[j] + arr[i] > inc[i]:
                inc[i] = inc[j] + arr[i]

    # Max sum of decreasing subsequence starting at i
    dec = arr[:]
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if arr[j] < arr[i] and dec[j] + arr[i] > dec[i]:
                dec[i] = dec[j] + arr[i]

    return max(inc[i] + dec[i] - arr[i] for i in range(n))


