def max_sub_array_sum_repeated(a, n, k):
    """Find the largest sum of a contiguous subarray in the modified array
    formed by repeating the given array ``a`` (of length ``n``) ``k`` times.

    Runs in O(n) time regardless of k.
    """
    if not a or n <= 0 or k <= 0:
        return 0

    def kadane(length):
        """Kadane's algorithm over the first ``length`` elements of the
        conceptually repeated array."""
        best = float('-inf')
        cur = 0
        for i in range(length):
            x = a[i % n]
            cur = x if cur < 0 else cur + x
            if cur > best:
                best = cur
        return best

    if k == 1:
        return kadane(n)

    # Best subarray that spans at most two copies of the array.
    best_two = kadane(2 * n)
    total = sum(a[:n])
    if total <= 0:
        # Spans of 3+ copies only append full copies of non-positive total,
        # so they can never beat the best span of at most two copies.
        return best_two

    # With a positive total, any subarray spanning m >= 3 copies consists of
    # a suffix of one copy, (m - 2) full copies, and a prefix of another
    # copy.  Its sum is maximized at m = k using the best suffix and prefix
    # sums of a single copy.
    max_pref, pref = float('-inf'), 0
    for i in range(n):
        pref += a[i]
        if pref > max_pref:
            max_pref = pref
    max_suf, suf = float('-inf'), 0
    for i in range(n - 1, -1, -1):
        suf += a[i]
        if suf > max_suf:
            max_suf = suf
    return max(best_two, max_suf + (k - 2) * total + max_pref)


