def get_max_sum(n):
    """
    Find the maximum sum possible using the equation:
        f(n) = max(f(n/2) + f(n/3) + f(n/4) + f(n/5), n)
    where the divisions are integer (floor) divisions.

    Uses top-down dynamic programming with memoization.

    Example:
        get_max_sum(60) == 106
    """
    memo = {0: 0}

    def f(x):
        if x in memo:
            return memo[x]
        res = max(f(x // 2) + f(x // 3) + f(x // 4) + f(x // 5), x)
        memo[x] = res
        return res

    return f(n)


