def cal_sum(n):
    """Calculate the sum of Perrin numbers P(0) through P(n).

    Perrin sequence: P(0)=3, P(1)=0, P(2)=2, P(n)=P(n-2)+P(n-3).
    e.g. cal_sum(9) == 3+0+2+3+2+5+5+7+10+12 == 49
    """
    if n < 0:
        return 0
    perrin = [3, 0, 2]
    if n < 3:
        return sum(perrin[: n + 1])
    for i in range(3, n + 1):
        perrin.append(perrin[i - 2] + perrin[i - 3])
    return sum(perrin)

