def binomial_Coeff(n, k):
    """Compute C(n, k) using a space-efficient DP (Pascal's triangle row)."""
    C = [0] * (k + 1)
    C[0] = 1
    for i in range(1, n + 1):
        for j in range(min(i, k), 0, -1):
            C[j] += C[j - 1]
    return C[k]


def sum_Of_product(n):
    """
    Sum of the product of consecutive binomial coefficients:
        sum_{k=0}^{n-1} C(n, k) * C(n, k+1)

    By the Vandermonde identity this equals C(2n, n-1).
    """
    return binomial_Coeff(2 * n, n - 1)

