def find_kth(arr1, arr2, k):
    """
    Find the k-th (1-indexed) element in the merged sorted order of two
    sorted arrays, in O(log k) time.

    >>> find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5)
    6
    """
    if not arr1:
        return arr2[k - 1]
    if not arr2:
        return arr1[k - 1]
    if k == 1:
        return min(arr1[0], arr2[0])

    # Compare the k//2-th elements of each array (clamped to array size).
    i = min(k // 2, len(arr1)) - 1
    j = min(k // 2, len(arr2)) - 1

    if arr1[i] <= arr2[j]:
        # arr1[0..i] are all among the first k-1 merged elements; discard them.
        return find_kth(arr1[i + 1:], arr2, k - (i + 1))
    else:
        # arr2[0..j] are all among the first k-1 merged elements; discard them.
        return find_kth(arr1, arr2[j + 1:], k - (j + 1))


if __name__ == "__main__":
    assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5) == 6
    print("All tests passed.")

