def jacobsthal_num(n):
    """Return the nth Jacobsthal number (0-indexed).

    Sequence: J(0)=0, J(1)=1, J(n) = J(n-1) + 2*J(n-2)
    -> 0, 1, 1, 3, 5, 11, 21, 43, 85, 171, 341, 683, 1365, 2731, ...
    """
    if n == 0:
        return 0
    if n == 1:
        return 1
    prev2, prev1 = 0, 1
    for _ in range(2, n + 1):
        prev2, prev1 = prev1, prev1 + 2 * prev2
    return prev1

