def check_expression(exp):
    """Check whether the brackets in the given expression are balanced.

    Supports (), {}, and []. Returns True if every opening bracket is
    closed by the matching bracket in the correct order, else False.
    """
    pairs = {')': '(', '}': '{', ']': '['}
    stack = []
    for char in exp:
        if char in '({[':
            stack.append(char)
        elif char in ')}]':
            if not stack or stack.pop() != pairs[char]:
                return False
    return not stack


if __name__ == "__main__":
    assert check_expression("{()}[{}]") == True
    assert check_expression("{()}[{]}") == False
    assert check_expression("()") == True
    assert check_expression("(") == False
    assert check_expression(")(") == False
    assert check_expression("{[()()]}") == True
    assert check_expression("") == True
    print("All tests passed.")

