def count_divisors(n):
    """Return True if n has an even number of divisors, False otherwise."""
    count = 0
    i = 1
    # Count divisors efficiently by iterating up to sqrt(n)
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1  # perfect square root counted once
            else:
                count += 2  # i and n // i are two distinct divisors
        i += 1
    return count % 2 == 0


if __name__ == "__main__":
    assert count_divisors(10)  # divisors: 1, 2, 5, 10 -> 4 (even)
    assert not count_divisors(9)  # divisors: 1, 3, 9 -> 3 (odd)
    assert not count_divisors(1)  # divisors: 1 -> 1 (odd)
    assert count_divisors(12)  # divisors: 1, 2, 3, 4, 6, 12 -> 6 (even)
    print("All tests passed.")

